input.command:
awk '
/Tests run: [0-9]+, Failures/ {
  match($0, /Tests run: ([0-9]+), Failures: ([0-9]+), Errors: ([0-9]+), Skipped: ([0-9]+)/, a);
  t+=a[1]; f+=a[2]; e+=a[3]; s+=a[4];
}
END { printf "TOTAL tests=%d failures=%d errors=%d skipped=%d\n", t, f, e, s }
' target/surefire-reports/*.txt
echo "--- files with failures/errors ---"
grep -l 'Failures: [1-9]\|Errors: [1-9]' target/surefire-reports/*.txt 2>/dev/null || echo "none"
